import SwiftUI

// 撮影地を指す手書き文字の種類
enum HereMark: String, CaseIterable {
    case none, here, koko

    var name: String {
        switch self {
        case .none: return "なし"
        case .here: return "Here!"
        case .koko: return "ココ!"
        }
    }

    // 白い文字の画像（色はあとから付ける）
    var image: UIImage? {
        switch self {
        case .none: return nil
        case .here: return HandwritingAssets.here
        case .koko: return HandwritingAssets.koko
        }
    }
}

// 手書き文字の画像（描いてもらった文字を切り抜いたもの）
enum HandwritingAssets {
    static let here: UIImage? = decode(hereBase64)
    static let koko: UIImage? = decode(kokoBase64)

    private static func decode(_ s: String) -> UIImage? {
        guard let data = Data(base64Encoded: s) else { return nil }
        return UIImage(data: data)
    }

    // 画像を好きな色に塗る（完成画像用）
    static func tinted(_ image: UIImage, color: UIColor) -> UIImage {
        let format = UIGraphicsImageRendererFormat()
        format.scale = image.scale
        format.opaque = false
        return UIGraphicsImageRenderer(size: image.size, format: format).image { ctx in
            color.setFill()
            ctx.fill(CGRect(origin: .zero, size: image.size))
            image.draw(at: .zero, blendMode: .destinationIn, alpha: 1)
        }
    }

    private static let hereBase64 = ""
    private static let kokoBase64 = ""
}

// 手書き文字から撮影地へ向かうカーブした矢印
enum HereArrow {
    // 手書き文字の高さ（文字の大きさに対する倍率）
    static let heightScale: CGFloat = 2.2

    /// labelRect：手書き文字の枠、dot：撮影地の点の位置
    static func path(from labelRect: CGRect, to dot: CGPoint, dotRadius: CGFloat, width: CGFloat) -> CGPath? {
        let center = CGPoint(x: labelRect.midX, y: labelRect.midY)
        let dx = dot.x - center.x, dy = dot.y - center.y
        let len = sqrt(dx * dx + dy * dy)
        guard len > 1 else { return nil }
        let ux = dx / len, uy = dy / len

        // 文字の枠のふちから少し離れたところから出発
        let tx = abs(ux) > 0.001 ? (labelRect.width / 2) / abs(ux) : .greatestFiniteMagnitude
        let ty = abs(uy) > 0.001 ? (labelRect.height / 2) / abs(uy) : .greatestFiniteMagnitude
        let t = min(tx, ty) + width * 2
        let start = CGPoint(x: center.x + ux * t, y: center.y + uy * t)
        // 青い点の少し手前で止める
        let end = CGPoint(x: dot.x - ux * dotRadius * 3, y: dot.y - uy * dotRadius * 3)

        let sx = end.x - start.x, sy = end.y - start.y
        let segLen = sqrt(sx * sx + sy * sy)
        guard segLen > width * 4 else { return nil }

        // 下にたわむようにカーブさせる
        var px = -sy / segLen, py = sx / segLen
        if py < 0 || (abs(py) < 0.1 && px < 0) { px = -px; py = -py }
        let bow = segLen * 0.25
        let control = CGPoint(x: (start.x + end.x) / 2 + px * bow, y: (start.y + end.y) / 2 + py * bow)

        let path = CGMutablePath()
        path.move(to: start)
        path.addQuadCurve(to: end, control: control)

        // 矢じり
        let ex = end.x - control.x, ey = end.y - control.y
        let el = max(sqrt(ex * ex + ey * ey), 0.001)
        let bx = -ex / el, by = -ey / el          // 先端から後ろ向き
        let head = width * 3.2
        let angle: CGFloat = .pi / 5
        func rotated(_ a: CGFloat) -> CGPoint {
            CGPoint(x: end.x + (bx * cos(a) - by * sin(a)) * head,
                    y: end.y + (bx * sin(a) + by * cos(a)) * head)
        }
        path.move(to: rotated(angle))
        path.addLine(to: end)
        path.addLine(to: rotated(-angle))
        return path
    }
}
